import{_ as h,o as t,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const y=JSON.parse('{"title":"Luật Chống Độc quyền","description":"","frontmatter":{},"headers":[],"relativePath":"vi/47-反垄断法.md","filePath":"vi/47-反垄断法.md","lastUpdated":1789183869000}'),a={name:"vi/47-反垄断法.md"};function u(g,n,r,l,o,d){return t(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="luat-chong-đoc-quyen" tabindex="-1">Luật Chống Độc quyền <a class="header-anchor" href="#luat-chong-đoc-quyen" aria-label="Permalink to &quot;Luật Chống Độc quyền&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Dự án</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>47</td></tr><tr><td>Mô-đun</td><td>Hệ thống pháp luật và khuôn khổ quản trị</td></tr><tr><td>Từ khóa cốt lõi</td><td>Chống độc quyền, chống cướp đoạt, cạnh tranh thị trường, độc quyền tài nguyên, độc quyền tu luyện</td></tr></tbody></table><h2 id="_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" tabindex="-1">1. Mục đích lập pháp và nguyên tắc cơ bản <a class="header-anchor" href="#_1-muc-đich-lap-phap-va-nguyen-tac-co-ban" aria-label="Permalink to &quot;1. Mục đích lập pháp và nguyên tắc cơ bản&quot;">​</a></h2><p>《Luật Chống Độc quyền》 là một trong năm luật pháp hỗ trợ của văn minh cộng sinh neo, nhằm ngăn ngừa và chấm dứt các hành vi độc quyền, bảo vệ cạnh tranh công bằng trên thị trường, nâng cao hiệu quả hoạt động kinh tế, duy trì lợi ích người tiêu dùng và lợi ích công cộng xã hội, đồng thời thúc đẩy sự phát triển lành mạnh của kinh tế cộng sinh. Trong văn minh cộng sinh neo, chống độc quyền không chỉ nhắm vào độc quyền trong lĩnh vực kinh tế truyền thống, mà còn vào các hình thức đặc biệt như độc quyền tài nguyên tu luyện, độc quyền tri thức và độc quyền位面.</p><p>Luật này thiết lập các nguyên tắc cơ bản sau:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th></tr></thead><tbody><tr><td>Nguyên tắc cạnh tranh công bằng</td><td>Duy trì trật tự thị trường cạnh tranh công bằng, cấm các hành vi độc quyền loại trừ hoặc hạn chế cạnh tranh</td></tr><tr><td>Nguyên tắc chống cướp đoạt</td><td>Cốt lõi của chống độc quyền là chống cướp đoạt, ngăn chặn người độc quyền thông qua vị thế độc quyền để cướp đoạt lợi ích của chúng sinh</td></tr><tr><td>Nguyên tắc mở cửa tài nguyên</td><td>Tài nguyên tu luyện công cộng và tri thức cơ bản phải được mở cửa cho toàn xã hội, cấm độc quyền tư nhân</td></tr><tr><td>Nguyên tắc cân bằng hiệu quả và công bằng</td><td>Chống độc quyền既要 bảo vệ hiệu quả cạnh tranh,也要 ngăn chặn lãng phí tài nguyên do phân tán quá mức</td></tr><tr><td>Nguyên tắc áp dụng liên位面</td><td>Luật chống độc quyền áp dụng cho tất cả các位面 và thị trường bên trong Hengyuanzhou, độc quyền liên位面 cũng bị quy định</td></tr></tbody></table><h2 id="_2-cac-loai-hanh-vi-đoc-quyen" tabindex="-1">2. Các loại hành vi độc quyền <a class="header-anchor" href="#_2-cac-loai-hanh-vi-đoc-quyen" aria-label="Permalink to &quot;2. Các loại hành vi độc quyền&quot;">​</a></h2><p>Các hành vi độc quyền được quy định bởi luật này bao gồm bốn loại sau:</p><h3 id="_1-thoa-thuan-đoc-quyen" tabindex="-1">(1) Thỏa thuận độc quyền <a class="header-anchor" href="#_1-thoa-thuan-đoc-quyen" aria-label="Permalink to &quot;(1) Thỏa thuận độc quyền&quot;">​</a></h3><p>Thỏa thuận độc quyền đề cập đến các thỏa thuận, quyết định hoặc các hành vi phối hợp khác loại trừ, hạn chế cạnh tranh, bao gồm:</p><ol><li><strong>Thỏa thuận độc quyền ngang</strong>: Các thỏa thuận giữa các nhà kinh doanh có quan hệ cạnh tranh về cố định giá, hạn chế sản lượng, phân chia thị trường, tẩy chay giao dịch chung, v.v.</li><li><strong>Thỏa thuận độc quyền dọc</strong>: Các thỏa thuận giữa nhà kinh doanh và đối tác giao dịch về cố định giá bán lại, hạn chế giá bán lại tối thiểu, v.v.</li><li><strong>Thỏa thuận độc quyền tài nguyên tu luyện</strong>: Các thỏa thuận giữa các tông môn tu luyện về phân chia khu vực tài nguyên tu luyện, thống nhất giá tài nguyên, hạn chế cung cấp tài nguyên, v.v.</li><li><strong>Thỏa thuận độc quyền tri thức</strong>: Các thỏa thuận giữa cơ sở giáo dục và tông môn tu luyện về phong tỏa pháp môn tu luyện, hạn chế truyền bá tri thức, thống nhất tiêu chuẩn học phí, v.v.</li></ol><h3 id="_2-lam-dung-vi-the-thong-tri-thi-truong" tabindex="-1">(2) Lạm dụng vị thế thống trị thị trường <a class="header-anchor" href="#_2-lam-dung-vi-the-thong-tri-thi-truong" aria-label="Permalink to &quot;(2) Lạm dụng vị thế thống trị thị trường&quot;">​</a></h3><p>Vị thế thống trị thị trường đề cập đến vị thế thị trường mà nhà kinh doanh có khả năng kiểm soát giá, số lượng hoặc các điều kiện giao dịch khác của hàng hóa trên thị trường liên quan, hoặc có khả năng cản trở, ảnh hưởng đến việc các nhà kinh doanh khác gia nhập thị trường liên quan. Các hành vi lạm dụng vị thế thống trị thị trường bao gồm:</p><table tabindex="0"><thead><tr><th>Loại hành vi</th><th>Biểu hiện cụ thể</th></tr></thead><tbody><tr><td>Định giá không công bằng</td><td>Bán hàng hóa với giá cao không công bằng hoặc mua hàng hóa với giá thấp không công bằng</td></tr><tr><td>Định giá cướp đoạt</td><td>Không có lý do chính đáng, bán hàng hóa với giá dưới chi phí để loại trừ đối thủ cạnh tranh</td></tr><tr><td>Từ chối giao dịch</td><td>Không có lý do chính đáng, từ chối giao dịch với đối tác</td></tr><tr><td>Hạn chế giao dịch</td><td>Không có lý do chính đáng, hạn chế đối tác chỉ được giao dịch với mình</td></tr><tr><td>Bán hàng gắn kết</td><td>Không có lý do chính đáng, bán hàng hóa gắn kết, hoặc đính kèm các điều kiện không hợp lý khác khi giao dịch</td></tr><tr><td>Đối xử phân biệt</td><td>Không có lý do chính đáng, thực hiện đối xử phân biệt về các điều kiện như giá giao dịch đối với các đối tác có cùng điều kiện</td></tr><tr><td>Phong tỏa tài nguyên tu luyện</td><td>Lợi dụng vị thế độc quyền tài nguyên tu luyện, từ chối cung cấp tài nguyên cần thiết cho đối thủ cạnh tranh hoặc người tiêu dùng</td></tr><tr><td>Phong tỏa tri thức</td><td>Lợi dụng vị thế độc quyền tri thức, phong tỏa pháp môn tu luyện cơ bản, ép buộc người học phải trả chi phí cao</td></tr></tbody></table><h3 id="_3-su-tap-trung-cua-nha-kinh-doanh" tabindex="-1">(3) Sự tập trung của nhà kinh doanh <a class="header-anchor" href="#_3-su-tap-trung-cua-nha-kinh-doanh" aria-label="Permalink to &quot;(3) Sự tập trung của nhà kinh doanh&quot;">​</a></h3><p>Sự tập trung của nhà kinh doanh đề cập đến các tình huống sau: sáp nhập nhà kinh doanh; nhà kinh doanh thông qua việc取得 cổ phiếu hoặc tài sản để取得 quyền kiểm soát đối với nhà kinh doanh khác; nhà kinh doanh thông qua hợp đồng v.v. để取得 quyền kiểm soát đối với nhà kinh doanh khác hoặc có khả năng gây ảnh hưởng quyết định đối với nhà kinh doanh khác.</p><p>Sự tập trung của nhà kinh doanh đạt tiêu chuẩn báo cáo phải được báo cáo trước cho cơ quan chấp hành chống độc quyền, và những người không được báo cáo không được thực hiện sự tập trung. Khi cơ quan chấp hành chống độc quyền xem xét sự tập trung của nhà kinh doanh, phải xem xét các yếu tố sau:</p><ol><li>Thị phần của các nhà kinh doanh tham gia sự tập trung trên thị trường liên quan và sức mạnh kiểm soát của họ đối với thị trường.</li><li>Mức độ tập trung thị trường của thị trường liên quan.</li><li>Tác động của sự tập trung nhà kinh doanh đối với việc gia nhập thị trường và tiến bộ công nghệ.</li><li>Tác động của sự tập trung nhà kinh doanh đối với người tiêu dùng và các nhà kinh doanh liên quan khác.</li><li>Tác động của sự tập trung nhà kinh doanh đối với việc mở cửa tài nguyên tu luyện và truyền bá tri thức.</li><li>Tác động của sự tập trung nhà kinh doanh đối với phát triển kinh tế quốc dân và sự tiến bộ chung của mọi tộc.</li></ol><h3 id="_4-lam-dung-quyen-hanh-chinh-đe-loai-tru-han-che-canh-tranh" tabindex="-1">(4) Lạm dụng quyền hành chính để loại trừ, hạn chế cạnh tranh <a class="header-anchor" href="#_4-lam-dung-quyen-hanh-chinh-đe-loai-tru-han-che-canh-tranh" aria-label="Permalink to &quot;(4) Lạm dụng quyền hành chính để loại trừ, hạn chế cạnh tranh&quot;">​</a></h3><p>Cơ quan hành chính và tổ chức được luật, quy định trao quyền có chức năng quản lý công việc công cộng không được lạm dụng quyền hành chính để thực hiện các hành vi sau:</p><ol><li>Hạn chế hoặc biến相 hạn chế đơn vị hoặc cá nhân kinh doanh, mua, sử dụng hàng hóa do nhà kinh doanh được chỉ định cung cấp.</li><li>Cản trở lưu thông tự do của hàng hóa giữa các khu vực, giữa các位面.</li><li>Loại trừ hoặc hạn chế nhà kinh doanh ngoài khu vực, nhà kinh doanh ngoài位面 tham gia hoạt động đấu thầu, mời thầu địa phương.</li><li>Loại trừ hoặc hạn chế nhà kinh doanh ngoài khu vực, nhà kinh doanh ngoài位面 đầu tư tại địa phương hoặc thành lập chi nhánh.</li><li>Ép buộc nhà kinh doanh tham gia các hành vi độc quyền được quy định trong luật này.</li><li>Đưa ra các quy định có nội dung loại trừ, hạn chế cạnh tranh.</li></ol><h2 id="_3-quy-tac-chong-đoc-quyen-đac-biet-trong-linh-vuc-tu-luyen" tabindex="-1">3. Quy tắc chống độc quyền đặc biệt trong lĩnh vực tu luyện <a class="header-anchor" href="#_3-quy-tac-chong-đoc-quyen-đac-biet-trong-linh-vuc-tu-luyen" aria-label="Permalink to &quot;3. Quy tắc chống độc quyền đặc biệt trong lĩnh vực tu luyện&quot;">​</a></h2><p>Lĩnh vực tu luyện là lĩnh vực trọng tâm của chống độc quyền trong văn minh cộng sinh neo, và luật này thiết lập các quy tắc đặc biệt:</p><ol><li><strong>Nghĩa vụ mở cửa pháp môn cơ bản</strong>: Pháp môn cơ bản của ba trăm hệ thống tu luyện nguồn gốc thuộc về tri thức công cộng, và không tổ chức hay cá nhân nào được độc quyền, phong tỏa hoặc truyền授 với phí.</li><li><strong>Phân phối công bằng tài nguyên tu luyện</strong>: Tài nguyên tu luyện công cộng được phân phối công bằng thông qua cơ chế hợp đồng sản xuất liên hợp, và cấm tông môn hoặc cá nhân độc quyền tài nguyên tu luyện chất lượng cao.</li><li><strong>Cấm phân biệt đối xử trong tu luyện</strong>: Tông môn tu luyện không được thiết lập các điều kiện phân biệt đối xử dựa trên tộc, xuất thân, trình độ tu luyện, v.v. trong tuyển sinh và truyền授.</li><li><strong>Nghĩa vụ chia sẻ tri thức cao cấp</strong>: Người tu luyện đạt tiêu chuẩn mạnh nhất位面 có nghĩa vụ chia sẻ với xã hội kinh nghiệm tu luyện và kết quả nghiên cứu của mình, trên cơ sở bảo hộ quyền sở hữu trí tuệ hợp lý.</li><li><strong>Chống độc quyền phát triển位面</strong>: Quyền phát triển位面 mới được phân phối thông qua cạnh tranh công khai, và cấm một vài thế lực độc quyền quyền phát triển位面.</li></ol><h2 id="_4-co-quan-chap-hanh-chong-đoc-quyen" tabindex="-1">4. Cơ quan chấp hành chống độc quyền <a class="header-anchor" href="#_4-co-quan-chap-hanh-chong-đoc-quyen" aria-label="Permalink to &quot;4. Cơ quan chấp hành chống độc quyền&quot;">​</a></h2><p>Nhà nước thành lập cơ quan chấp hành chống độc quyền, chịu trách nhiệm công tác chấp hành chống độc quyền, và thực hiện các chức năng sau:</p><ol><li>Nghiên cứu, soạn thảo chính sách cạnh tranh liên quan.</li><li>Tổ chức điều tra, đánh giá tình hình cạnh tranh tổng thể của thị trường, và phát hành báo cáo đánh giá.</li><li>Soạn thảo, phát hành hướng dẫn chống độc quyền.</li><li>Phối hợp công tác chấp hành hành chính chống độc quyền.</li><li>Điều tra, xử lý các vụ việc thỏa thuận độc quyền, lạm dụng vị thế thống trị thị trường, thực hiện sự tập trung nhà kinh doanh trái phép, v.v.</li><li>Điều tra, xử lý các hành vi lạm dụng quyền hành chính để loại trừ, hạn chế cạnh tranh.</li></ol><p>Cơ quan chấp hành chống độc quyền thực hiện quyền hạn một cách độc lập theo pháp luật, không bị sự can thiệp của cơ quan hành chính, tổ chức xã hội và cá nhân.</p><h2 id="_5-trach-nhiem-phap-ly" tabindex="-1">5. Trách nhiệm pháp lý <a class="header-anchor" href="#_5-trach-nhiem-phap-ly" aria-label="Permalink to &quot;5. Trách nhiệm pháp lý&quot;">​</a></h2><p>Các hành vi vi phạm quy định của luật này sẽ chịu trách nhiệm sau tùy theo mức độ nghiêm trọng của vi phạm:</p><ul><li>Kết luận và thực hiện thỏa thuận độc quyền, ra lệnh chấm dứt hành vi trái phép, tịch thu thu nhập bất hợp pháp, và phạt tiền từ 1% đến 10% doanh thu bán hàng năm trước.</li><li>Lạm dụng vị thế thống trị thị trường, ra lệnh chấm dứt hành vi trái phép, tịch thu thu nhập bất hợp pháp, và phạt tiền từ 1% đến 10% doanh thu bán hàng năm trước.</li><li>Thực hiện sự tập trung nhà kinh doanh trái phép, ra lệnh chấm dứt thực hiện sự tập trung, phân phối cổ phiếu hoặc tài sản trong thời hạn, chuyển nhượng kinh doanh trong thời hạn, và phạt tiền dưới 500.000 nhân dân tệ.</li><li>Lạm dụng quyền hành chính để loại trừ, hạn chế cạnh tranh, cơ quan cấp trên ra lệnh khắc phục, và给予 người chịu trách nhiệm trực tiếp cũng như người chịu trách nhiệm trực tiếp khác kỷ luật theo pháp luật.</li><li>Hành vi độc quyền gây thiệt hại cho người khác, chịu trách nhiệm bồi thường dân sự theo pháp luật.</li><li>Trường hợp nghiêm trọng cấu thành tội phạm, truy cứu trách nhiệm hình sự theo pháp luật.</li></ul><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>《Luật Chống Độc quyền》 là vũ khí pháp luật của chủ nghĩa chống cướp đoạt của văn minh cộng sinh neo trong lĩnh vực kinh tế và tu luyện. Bằng cách quy định thỏa thuận độc quyền, lạm dụng vị thế thống trị thị trường, sự tập trung nhà kinh doanh và độc quyền hành chính, đặc biệt là thiết lập các quy tắc đặc biệt đối với độc quyền tài nguyên tu luyện và độc quyền tri thức, nó đảm bảo cạnh tranh thị trường và sự mở cửa công bằng của tài nguyên tu luyện, ngăn chặn độc quyền trở thành hình thức mới của việc cướp đoạt chúng sinh, và duy trì môi trường thể chế cạnh tranh công bằng cho sự tiến bộ chung của mọi tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>40-共生宪法总纲 (Nguyên tắc chung Hiến pháp Cộng sinh)</li><li>42-消费者保护法 (Luật Bảo vệ Người tiêu dùng)</li><li>18-修炼资源开放机制 (Cơ chế Mở cửa Tài nguyên Tu luyện)</li><li>04-反掠夺主义核心论纲 (Chương trình cốt lõi Chủ nghĩa Chống Cướp đoạt)</li></ul>',35)])])}const e=h(a,[["render",u]]);export{y as __pageData,e as default};
